cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void softmax_kernel(const half* input, half* output, int batch_size, int num_features) {
    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const int feature_offset = batch_idx * num_features;
    const half* input_row = input + feature_offset;
    half* output_row = output + feature_offset;

    // Find max value for numerical stability
    half max_val = input_row[0];
    for (int i = 1; i < num_features; i++) {
        max_val = fmaxf(__half2float(max_val), __half2float(input_row[i])) ? max_val : input_row[i];
    }

    // Compute exp(x - max) and sum
    float sum = 0.0f;
    for (int i = 0; i < num_features; i++) {
        float exp_val = expf(__half2float(input_row[i]) - __half2float(max_val));
        output_row[i] = __float2half(exp_val);
        sum += exp_val;
    }

    // Normalize by sum
    float inv_sum = 1.0f / sum;
    for (int i = 0; i < num_features; i++) {
        output_row[i] = __float2half(__half2float(output_row[i]) * inv_sum);
    }
}

extern "C" void launch_softmax(const half* input, half* output, int batch_size, int num_features) {
    const int threads_per_block = 256;
    const int blocks = (batch_size + threads_per_block - 1) / threads_per_block;
    softmax_kernel<<<blocks, threads_per_block>>>(input, output, batch_size, num_features);
}
"""

